import { useState, component, useEffect, useLayoutEffect, useRef } from 'haunted';
import { html } from 'lit';
import { ref, createRef } from 'lit/directives/ref.js';

const KEYCODES = {
  ENTER: 'Enter',
  TAB: 'Tab',
  BACKSPACE: 'Backspace',
  ESCAPE: 'Escape'
}

// TODO: Already this needs some refactoring ewww
// Styles are kind of unreadable (generated by claude)
// & keyboard logic might be better off moved to the parent
// This cell should not really care about


function TableCell({
  identifier,
  rowIndex,
  colIndex,
  field,
  type,
  format,
  focused,
  editing,
  customCell,
  renderValue,
  data,
  value
}) {
  const [editList, setEditList] = useState(() => Array.isArray(value) ? value : []);
  const divRef = createRef();

  const contentEditableRef = createRef();
  const checkboxRef = createRef();

  useEffect(() => {
    // Sync local state when parent value changes (e.g., after save/cancel)
    setEditList(Array.isArray(value) ? value : []);
  }, [value]);

  useLayoutEffect(() => {
    if (type === "checkbox" && (focused || editing)) {
      checkboxRef.current.focus()
      return;
    }

    // Generic editing
    if (editing) {
      if (contentEditableRef.current) {
        contentEditableRef.current.focus();
        // Move caret to end
        const range = document.createRange();
        range.selectNodeContents(contentEditableRef.current);
        range.collapse(false);
        const sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
      }
    } else if (focused) {
        divRef.current.focus();
    }
  }, [focused, editing]);

  const handleSingleCellKeyDown = (e) => {
    if (e.key === KEYCODES.ENTER) {
      e.preventDefault();
      e.stopPropagation();

      if (editing) {
        let textValue = contentEditableRef.current?.innerText ?? '';
        textValue = textValue.trim();
        contentEditableRef.current.innerText = '';
        dispatchDataChange(e, field, textValue);
      }
    }
  }

  function handleCellBlur(e) {
    if (type === 'multiple') {
      e.target.innerText = ''; // Reset input on blur
    }
    divRef.current?.dispatchEvent(new CustomEvent('cell-cancel', {
      detail: { identifier, field, row: rowIndex, col: colIndex },
      bubbles: true,
      composed: true
    }));
  }

  function renderSingleCell() {
    return html`
      <span class="cell-content" style="${!editing ? 'display: block;' : 'display: none;'}">
        ${renderValue ? renderValue(value) : value}
      </span>
      <span
        class="cell-content"
        style="${editing ? 'display: block;' : 'display: none;'}"
        contenteditable="${editing ? 'true' : 'false'}"
        @keydown=${handleSingleCellKeyDown}
        @blur=${handleCellBlur}
        ${ref(el => {
          contentEditableRef.current = el;
          if (el) {
            el.innerText = value ?? '';
            el.addEventListener('beforeinput', (e) => {
              if (e.inputType === 'insertParagraph' || e.inputType === 'insertLineBreak') {
                e.preventDefault();
              }
            });
          }
        })}
      ></span>
    `;
  }

  function handleAddItem(e, newItem) {
    let newList = [...editList]

    if (newItem && newItem.trim() !== '') {
      newList = [...newList, newItem.trim()];
    }
    setEditList(newList);

    dispatchDataChange(e, field, newList);

    return newList;
  }

  function handleRemoveItem(e, index) {
    const newList = editList.filter((_, i) => i !== index);
    setEditList(newList);
    dispatchDataChange(e, field, newList);
    return newList;
  }

  function dispatchDataChange(e, updatedField, newValue) {
    divRef.current?.dispatchEvent(new CustomEvent('cell-change', {
      detail: { identifier, field: updatedField, value: newValue, row: rowIndex, col: colIndex },
      bubbles: true,
      composed: true
    }));
  }

  function handleListInputKeyDown(e) {
    if (!editing) return;
    if (e.key === KEYCODES.ENTER) {
      e.preventDefault();
      const newItem = e.target.innerText.trim();
      handleAddItem(e, newItem)
    } else if (e.key === KEYCODES.BACKSPACE) {
      // If there is input, return
      // Else, remove a button
      const input = e.target.innerText.trim();
      if (input && input.length > 0) {
        return;
      }

      if (editList.length === 0) {
        return;
      }
      // Visual update only -- commits only when Entered
      handleRemoveItem(e, editList.length - 1);
    }
  }

  function renderListCell() {
    const displayWithFormat = item => {
      switch (format) {
        case 'phone':
          return html`<a href="tel:${item}" class="tag-link" tabindex="-1">${item}</a>`;
        case 'email':
          return html`<a href="mailto:${item}" class="tag-link" tabindex="-1">${item}</a>`;
        default:
          return html`<a href="${item}" target="_blank" rel="noopener noreferrer" class="tag-link" tabindex="-1">${item}</a>`;
      }
    };

    const displayItem = (item, index) => renderValue ? renderValue(item, index) : displayWithFormat(item);

    return html`
      <div class="tag-list ${editing ? 'editing' : ''}">
        ${editList.map((item, i) => editing
          ? html`
            <button type="button" @mousedown=${e => e.preventDefault()} @click=${e => handleRemoveItem(e, i)}>
              <span class="tag-label">${item}</span>
              <span class="tag-remove">×</span>
            </button>`
          : displayItem(item, i)
        )}
        <span
          class="tag-input"
          contenteditable="${editing ? 'true' : 'false'}"
          data-placeholder=${editing ? 'Add item...' : ''}
          @blur=${handleCellBlur}
          @keydown=${handleListInputKeyDown}
          ${ref(el => {
            contentEditableRef.current = el;
            if (el) {
              el.innerText = '';
              el.addEventListener('beforeinput', (e) => {
                if (e.inputType === 'insertParagraph' || e.inputType === 'insertLineBreak') {
                  e.preventDefault();
                }
              });
            }
          })}
        ></span>
       
      </div>
    `;
  }

  function renderCheckboxCell() {
    return html`
        <div style="display:flex; align-items:center; justify-content:center;">
            <input type="checkbox" style="margin: 0" tabIndex="-1"
              ${ref(el => {
                checkboxRef.current = el;
                if (el && !el.dataset.initialized) {
                  el.checked = !!value;
                  el.dataset.initialized = 'true';
                }
              })}
              @change=${(e) => dispatchDataChange(e, field, e.target.checked)}
            />
          </div>
    `;
  }

  function renderCell() {
    if (customCell) {
      return customCell(data);
    }

    switch (type) {
      case 'multiple':
        return renderListCell();
      case 'checkbox':
        return renderCheckboxCell()
      default:
        return renderSingleCell();
    }
  }

  return html`
        <div
            tabIndex="-1"
            data-field=${field} 
            ${ref(el => {
              divRef.current = el;
            })}
        >
            ${renderCell()}
        </div>
    `;
}

customElements.define('civ-table-cell', component(TableCell, { observedAttributes: ['identifier', 'rowIndex', 'colIndex', 'field', 'data', 'value'], useShadowDOM: false }));